# Created by OpenAI
"""Shared MoE arithmetic, tile-layout, asynchronous-copy, and reduction primitives."""
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _sigmoid(x):
    return 1.0 / (1.0 + gl.exp(-x))

@gluon.jit
def _weight_offset(n, k, K: gl.constexpr):
    return n // 16 * K * 16 + k // 16 * 256 + n % 16 * 16 + k % 16
